window.AUTH=window.AUTH||{};window.AUTH["19-8709"]={"d":"19-8709","id":"2020/19-8709","n":"Greer v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Gregory Greer","date":"2021-02-22","url":"https://www.supremecourt.gov/DocketPDF/19/19-8709/169605/20210222171108435_Greer%20Merits%20Brief%20Final.pdf","side":"pet","n":78},{"k":"respondent","label":"Brief of respondent United States of America","date":"2021-03-24","url":"https://www.supremecourt.gov/DocketPDF/19/19-8709/172890/20210324163945837_19-8709bsUnitedStates.pdf","side":"res","n":67},{"k":"reply","label":"Reply of petitioner Gregory Greer","date":"2021-04-09","url":"https://www.supremecourt.gov/DocketPDF/19/19-8709/175325/20210409130042095_Greer%20Merits%20Reply%20in%20Shell_FINAL.pdf","side":"pet","n":36}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/593us2r46_1qm2.pdf","tr":true,"items":[{"t":"case","label":"Arizona v. Fulminante","cite":"499 U.S. 279","y":1991,"id":"1990/89-839","sc":1,"op":3,"sum":"The Court held that Fulminante was coerced to confess in violation of the Fifth and Fourteenth Amendments. The Court found that \"it was fear of physical violence, absent protection from his friend Sarivola, which motivated Fulminante to confess.\" This motivation invalidated his confession. Since Fulminante's confession to Donna Sarivola was closely tied to his first coerced confession, the Court dismissed both.","sumSrc":"Oyez","by":{"0":"14","1":"30, 31"}},{"t":"case","label":"Blakely v. Washington","cite":"542 U.S. 296","y":2004,"id":"2003/02-1632","sc":1,"op":3,"sum":"The Court held that an exceptional sentence increase based on the judge's determination that Blakely had acted with \"deliberate cruelty\" violated Blakely's Sixth Amendment right to trial by jury.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Betterman v. Montana","cite":"136 S. Ct. 1609","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./136/1609/","sc":1,"by":{"0":"35"}},{"t":"case","label":"Burks v. United States","cite":"437 U.S. 1","y":1978,"id":"1977/76-6528","sc":1,"sum":"The Double Jeopardy Clause of the Fifth Amendment precludes a second trial once the reviewing court has found the evidence insufficient to sustain the jury's verdict of guilty, and the only \"just\" remedy available for that court under 28 U. S. C. § 2106 is the entry of a judgment of acquittal.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15"}},{"t":"case","label":"Clyatt v. United States","cite":"197 U.S. 207","y":1905,"id":"scdb/1904-129","sc":1,"ar":2,"sum":"Peonage is a status or condition of compulsory service based upon the indebtedness of the peon to the master. The service is enforced unless the debt be paid, and however created, it is involuntary, servitude within the prohibition of the Thirteenth Amendment to the Federal Constitution.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"12, 40","1":"29","2":"2, 4"}},{"t":"case","label":"Crawford v. Washington","cite":"541 U.S. 36","y":2004,"id":"2003/02-9410","sc":1,"sum":"The Court sided with Crawford and ruled that the Sixth Amendment's Confrontation Clause gives defendants the right to confront witnesses and cross-examine their testimony. This includes testimony police gather. The Court reasoned that the Framers intended the Confrontation Clause to prohibit out-of-court testimony as evidence against defendants.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Cunningham v. California","cite":"549 U.S. 270","y":2007,"id":"2006/05-6551","sc":1,"sum":"The Court ruled 6-3 that California's Determinate Sentencing Law was inconsistent with the Sixth Amendment right to trial by jury.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Descamps v. United States","cite":"570 U.S. 254","y":2013,"id":"2012/11-9540","sc":1,"sum":"The Court held that it was improper to apply the categorical approach in which the courts apply elements of a prior conviction with elements of a generic crime in order to enhance a sentence under the ACCA.","sumSrc":"Oyez","by":{"0":"23","2":"8, 9"}},{"t":"case","label":"Duncan v. Louisiana","cite":"391 U.S. 145","y":1968,"id":"1967/410","sc":1,"sum":"The Court ruled that the right to a jury trial in state prosecutions where sentences may be as long as two years were protected under the Sixth and Fourteenth Amendments.","sumSrc":"Oyez","by":{"0":"20, 21"}},{"t":"case","label":"Dunn v. United States","cite":"442 U.S. 100","y":1979,"id":"1978/77-6949","sc":1,"sum":"Petitioner's testimony before a grand jury in June 1976 implicated one Musgrave in various drug-related offenses, and an indictment of Musgrave followed. On September 30, 1976, petitioner recanted his testimony in an oral statement made under oath in the office of Musgrave's attorney. Musgrave then moved to dismiss his indictment, alleging that it was based on perjured testimony. At an evidentiary hearing on this …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31","2":"8"}},{"t":"case","label":"Esquivel-Quintana v. Sessions","cite":"137 S. Ct. 1562","y":2017,"id":"2016/16-54","sc":1,"sum":"The Court determined that the crime of “unlawful sexual intercourse with a minor” as defined by California law cannot be categorically considered the aggravated felony of “sexual abuse of a minor” for the purpose of mandatory removal under the Immigration and Nationality Act (INA).","sumSrc":"Oyez","by":{"0":"13"}},{"t":"case","label":"Greer v. United States","cite":"140 S. Ct. 41","y":2019,"url":"https://www.courtlistener.com/c/S.%20Ct./140/41/","sc":1,"by":{"0":"1"}},{"t":"case","label":"Gregg v. United States","cite":"394 U.S. 489","y":1969,"id":"1968/453","sc":1,"sum":"Petitioner argues that his conviction for jeopardizing the lives of postal custodians while robbing them should be reversed because the trial judge read the presentence report before the jury returned its verdict, in violation of Fed. Rule Crim. Proc.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36, 37"}},{"t":"case","label":"Griffith v. Kentucky","cite":"479 U.S. 314","y":1987,"id":"1986/85-5221","sc":1,"sum":"The Court held that after a new rule had been decided in a particular case, \"the integrity of judicial review requires that we apply that rule to all similar cases pending on direct review.\" The Court reasoned that selective application of new rules violated the principle of treating similarly situated defendants on an equal basis.","sumSrc":"Oyez","by":{"0":"5, 33, 34"}},{"t":"case","label":"Hankerson v. North Carolina","cite":"432 U.S. 233","y":1977,"id":"1976/75-6568","sc":1,"sum":"Prior to the decision in Mullaney v. Wilbur, 421 U. S. 684, petitioner was convicted in a North Carolina court of second-degree murder over his claim that he acted in self-defense. The trial judge had instructed the jury that if the State proved beyond a reasonable doubt that petitioner intentionally killed the victim with a deadly weapon the law raised presumptions that the killing was unlawful and that it was done …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Hicks v. United States","cite":"137 S. Ct. 2000","y":2017,"url":"https://www.courtlistener.com/c/S.%20Ct./137/2000/","sc":1,"by":{"0":"41","2":"11, 12"}},{"t":"case","label":"Holmes v. South Carolina","cite":"547 U.S. 319","y":2006,"id":"2005/04-1327","sc":1,"sum":"The opinion by Justice Samuel Alito - his first as a Supreme Court Justice - held that evidence of third-party guilt brought by the defense could not be excluded only on the basis of the strength of the prosecution's case.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Joseph v. United States","cite":"135 S. Ct. 705","y":2014,"url":"https://www.courtlistener.com/c/S.%20Ct./135/705/","sc":1,"sum":"Stating that the defendant’s failure to object in the district court reflected “not a lack of diligence, but merely a want of clairvoyance”.","sumSrc":"brief:0","by":{"0":"33"}},{"t":"case","label":"Johnson v. United States","cite":"520 U.S. 461","y":1997,"id":"1996/96-203","sc":1,"op":1,"sum":"The Court held that the trial court's action in this case was not \"plain error\" of the sort which an appellate court may notice under Federal Rule of Criminal Procedure 52(b).","sumSrc":"Oyez","by":{"0":"30","1":"passim","2":"8, 12, 13"}},{"t":"case","label":"Leland v. Oregon","cite":"343 U.S. 790","y":1952,"id":"scdb/1951-094","sc":1,"sum":"These statutes did not deprive appellant of life and liberty without due process of law in violation of the Fourteenth Amendment of the Federal Constitution.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Lewis v. United States","cite":"146 U.S. 370","y":1892,"id":"scdb/1892-037","sc":1,"sum":"Iu trials for. felonies, it is not in the power of the prisoner, either by himself or his counsel, to waive the right to be personally present during the trial.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Marshall v. United States","cite":"360 U.S. 310","y":1959,"id":"1958/383","sc":1,"sum":"The harm to petitioner that resulted when prejudicial information denied admission into evidence was brought before jurors through newspapers requires that a new trial be granted. Pp. 310-313. 258 F. 2d 94, reversed. George J. Francisargued the cause for petitioner. With him on the brief were Omer Griffin and Frances De Lost.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"McCormick v. United States","cite":"500 U.S. 257","y":1991,"id":"1990/89-1918","sc":1,"sum":"Petitioner McCormick, a member of the West Virginia House of Delegates in 1984, was a leading advocate of a legislative program allowing foreign medical school graduates to practice under temporary permits while studying for the state licensing exams. Some doctors practiced for years under the program, as they repeatedly failed those exams. He sponsored a bill, sought by an organization of those doctors, extending …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Morissette v. United States","cite":"342 U.S. 246","y":1952,"id":"scdb/1951-028","sc":1,"sum":"1. A criminal intent is an essential element of an offense under 18 U. S. C. § 641, which provides that \"whoever embezzles, steals, purloins, or knowingly converts\" property -of the United States is punishable by fine and imprisonment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22, 25"}},{"t":"case","label":"Neder v. United States","cite":"527 U.S. 1","y":1999,"id":"1998/97-1985","sc":1,"op":4,"ar":10,"sum":"The Court held 6-3 that under the harmless-error rule, which applies to a jury instruction that omits an element of an offense, the trial court's error did not render Neder's trial \"fundamentally unfair.\" Thus, the error was harmless.","sumSrc":"Oyez","by":{"0":"passim","1":"10, 17, 30, 33, 34","2":"passim"}},{"t":"case","label":"Patterson v. New York","cite":"432 U.S. 197","y":1977,"id":"1976/75-1861","sc":1,"sum":"New York law requiring that the defendant in a prosecution for seconddegree murder prove by a preponderance of the evidence the affirmative defense of extreme emotional disturbance in order to reduce the crime to manslaughter held not to violate the Due Process Clause of the Fourteenth Amendment. Mullaney v. Wilbur, 421 U. S. 684, distinguished.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Pope v. Illinois","cite":"481 U.S. 497","y":1987,"id":"1986/85-1973","sc":1,"sum":"The Court held that a jury may not be instructed to apply community standards regarding the value of a work to satisfy the third prong of the obscenity test established by the Court in Miller v. California.","sumSrc":"Oyez","by":{"0":"15","1":"30"}},{"t":"case","label":"Rehaif v. United States","cite":"139 S. Ct. 2191","y":2019,"id":"2018/17-9560","sc":1,"op":35,"ar":13,"sum":"In a prosecution under 18 U. S. C. §922(g) and §924(a)(2), the Government must prove both that the defendant knew he possessed a firearm and that he knew he belonged to the relevant category of persons barred from possessing a firearm.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"1, 2, 4","1":"2, 7, 11, 12, 34, 39","2":"4, 15"}},{"t":"case","label":"Rock v. Arkansas","cite":"483 U.S. 44","y":1987,"id":"1986/86-130","sc":1,"sum":"The Court held that Arkansas’s blanket ban on all hypnotically refreshed testimony infringed on Vickie Rock’s Fourteenth, Fifth, and Sixth Amendment right to testify on her own behalf.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Rosales-Mireles v. United States","cite":"138 S. Ct. 1897","y":2018,"id":"2017/16-9493","sc":1,"ar":2,"sum":"The Court held that a miscalculation of a Federal Guidelines sentencing range that has been determined to be plain and to affect a defendant’s substantial rights calls for a court of appeals to exercise its discretion under Federal Rule of Criminal Procedure 52(b) to vacate the defendant’s sentence in the ordinary case.","sumSrc":"Oyez","by":{"0":"15","1":"42","2":"5, 7, 11"}},{"t":"case","label":"Shepard v. United States","cite":"544 U.S. 13","y":2005,"id":"2004/03-9168","sc":1,"sum":"The Court held that while a guilty plea could qualify as a predicate offense under the ACCA, courts may only look to the following when determining if that plea admitted to generic burglary: the terms of the charging document, the terms of a plea agreement, or a judicial record in which the defendant confirmed the factual basis for the plea (such as conversation between defendant and judge).","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Sparf v. United States","cite":"156 U.S. 51","y":1895,"id":"scdb/1894-076","sc":1,"sum":"If one of two persons accused of having together committed the crime of murder makes a voluntary confession in the presence of the other, under such circumstances that he would naturally have contradicted it if he did not assent, the confession is admissible in evidence against both.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"25, 26"}},{"t":"case","label":"Sullivan v. Louisiana","cite":"508 U.S. 275","y":1993,"id":"1992/92-5129","sc":1,"op":1,"sum":"A constitutionally deficient reasonable-doubt instruction cannot be harmless error.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"29, 30","2":"10"}},{"t":"case","label":"United States v. Booker","cite":"543 U.S. 220","y":2005,"id":"2004/04-104","sc":1,"sum":"The Court held that the Sentencing Guidelines, where they allow judges to enhance sentences using facts not reviewed by juries, violated the Sixth Amendment right to trial by jury. The sentences of Booker and Fanfan, based partly on facts determined only by judges, were therefore unconstitutional.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"United States v. Brasfield","cite":"272 U.S. 448","y":1926,"id":"scdb/1926-005","sc":1,"sum":"1. An inquiry, put by the trial judge to a jury unable to agree, asking the extent of its division numerically, is per se ground for reversal.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"United States v. Ceron","cite":"775 F.3d 222","y":2014,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/775/222/","by":{"0":"34","1":"32"}},{"t":"case","label":"United States v. Conti","cite":"804 F.3d 977","y":2015,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/804/977/","by":{"0":"34","1":"32"}},{"t":"case","label":"United States v. Cotton","cite":"535 U.S. 625","y":2002,"id":"2001/01-687","sc":1,"op":1,"sum":"The Court held that the omission from a federal indictment of a fact that enhances the statutory maximum sentence does not justify a Court of Appeals' vacating the enhanced sentence, even though the defendant did not object in the trial court.","sumSrc":"Oyez","by":{"0":"30","1":"11, 23, 24, 31, 42"}},{"t":"case","label":"United States v. Delgado","cite":"672 F.3d 320","y":2012,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/672/320/","by":{"0":"27"}},{"t":"case","label":"United States v. Dominguez Benitez","cite":"542 U.S. 74","y":2004,"id":"2003/03-167","sc":1,"op":4,"sum":"The Court ruled that the judge's error most likely had no effect on Dominguez's decision to plead guilty, because he had already confessed to the crime and had little chance of winning at trial. Under Rule 52, a plain error is an \"error that affects substantial rights.\" Because the error did not harm Dominguez - he would likely have pled guilty anyway - it was not a reversible plain error.","sumSrc":"Oyez","by":{"0":"17, 19","1":"8, 14, 15, 16, 20","2":"5"}},{"t":"case","label":"United States v. Duran","cite":"133 F.3d 1324","y":1998,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/133/1324/","by":{"0":"27"}},{"t":"case","label":"United States v. Figueroa","cite":"683 F.3d 69","y":2012,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/683/69/","sum":"Describing a court’s efforts at preventing jurors from be ing influenced by improper outside factors as a “protective shield”.","sumSrc":"brief:0","by":{"0":"24"}},{"t":"case","label":"United States v. Gaudin","cite":"515 U.S. 506","y":1995,"id":"1994/94-514","sc":1,"sum":"The trial judge's refusal to submit the question of \"materiality\" to the jury was unconstitutional.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"United States v. Gaydos","cite":"108 F.3d 505","y":1997,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/108/505/","by":{"0":"27"}},{"t":"case","label":"United States v. Hall","cite":"610 F.3d 727","y":2010,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/610/727/","by":{"0":"34","1":"32"}},{"t":"case","label":"United States v. Haymond","cite":"139 S. Ct. 2369","y":2019,"id":"2018/17-1672","sc":1,"sum":"The Tenth Circuit’s judgment—that 18 U. S. C. §3583(k)’s last two sentences are unconstitutional and unenforceable—is vacated, and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"21, 22, 40, 41"}},{"t":"case","label":"United States v. Houston","cite":"792 F.3d 663","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/792/663/","by":{"0":"26"}},{"t":"case","label":"United States v. Johnson","cite":"821 F.3d 1194","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/821/1194/","by":{"0":"27","2":"19"}},{"t":"case","label":"United States v. Lane","cite":"474 U.S. 438","y":1986,"id":"1985/84-744","sc":1,"sum":"James Lane and his son Dennis, respondents in No. 84-744, were indicted on counts for, interalia,mail fraud in connection with insurance claims that were made and that insurers paid for fire damage to a restaurant and duplex that James had hired a professional arsonist to burn. The restaurant was operated by James in partnership with others. Count 1 charged James with mail fraud with regard to that fire. The duplex …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10"}},{"t":"case","label":"United States v. Lockhart","cite":"947 F.3d 187","y":2020,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/947/187/","op":1,"by":{"0":"38","1":"38"}},{"t":"case","label":"United States v. Maez","cite":"960 F.3d 949","y":2020,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/960/949/","sum":"Observing in analogous case that if “the trial records were left bare of such information,” it was “largely because Old Chief stipulations barred the government from offering it”.","sumSrc":"brief:1","by":{"0":"18","1":"25"}},{"t":"case","label":"United States v. Makkar","cite":"810 F.3d 1139","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/810/1139/","sum":"Holding that it “surely” implicates the integrity of judicial proceedings when a defendant is “relegated to federal prison even though the government concedes it hasn’t proven what the law demands it must prove to send him there”.","sumSrc":"brief:2","by":{"0":"40","2":"11"}},{"t":"case","label":"United States v. Marcus","cite":"560 U.S. 258","y":2010,"id":"2009/08-1341","sc":1,"ar":1,"sum":"The Court held that an appellate court may correct an error not raised at trial only when the appellant demonstrates that: (1) there is an error; (2) the error is clear and obvious; (3) the error affected the appellant's substantial rights; and (4) the error seriously affects the fairness, integrity, or public reputation of judicial proceedings.","sumSrc":"Oyez","by":{"0":"10","2":"13"}},{"t":"case","label":"United States v. Martinez","cite":"136 F.3d 972","y":1998,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/136/972/","by":{"0":"34","1":"32"}},{"t":"case","label":"United States v. McDonald","cite":"336 F.3d 734","y":2003,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/336/734/","by":{"0":"34","1":"32"}},{"t":"case","label":"United States v. Mechanik","cite":"475 U.S. 66","y":1986,"id":"1985/84-1640","sc":1,"sum":"However diligent the defendants may have been in seeking to discover the basis for the claimed violation of Rule 6(d), the petit jury's guilty verdict rendered harmless any error in the grand jury's charging decision that may have flowed from the violation. In such case, the societal costs of retrial are far too substantial to justify setting aside the verdict simply because of an error in the grand jury proceeding. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15","1":"17, 18, 31","2":"6"}},{"t":"case","label":"United States v. Nasir","cite":"982 F.3d 144","y":2020,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/982/144/","sum":"Recognizing “thoughtful members of the public” would be uncomfortable if a court ignored past breaches of due process because “we all know he’s guilty”.","sumSrc":"brief:2","by":{"0":"passim","1":"22, 23, 32, 38","2":"passim"}},{"t":"case","label":"United States v. O’Brien","cite":"560 U.S. 218","y":2010,"id":"2009/08-1569","sc":1,"sum":"The Court held that the fact that a firearm was a machine gun is an element to be proved to the jury beyond a reasonable doubt, not a sentencing factor to be proved to the judge at sentencing.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"United States v. Olano","cite":"507 U.S. 725","y":1993,"id":"1992/91-1306","sc":1,"op":3,"ar":1,"sum":"The presence of the alternate jurors during jury deliberations was not an error that the Court of Appeals was authorized to correct under Rule 52(b).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"passim","2":"passim"}},{"t":"case","label":"United States v. Perez-Montanez","cite":"202 F.3d 434","y":2000,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/202/434/","by":{"0":"34","1":"32"}},{"t":"case","label":"United States v. Reed","cite":"941 F.3d 1018","y":2019,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/941/1018/","by":{"0":"16, 17, 19"}},{"t":"case","label":"United States v. Rufai","cite":"732 F.3d 1175","y":2013,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/732/1175/","by":{"0":"27"}},{"t":"case","label":"United States v. Sabillon-Umana","cite":"772 F.3d 1328","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/772/1328/","by":{"0":"41, 42"}},{"t":"case","label":"United States v. Twitty","cite":"641 F. App’x 801","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/641/801/","by":{"0":"26"}},{"t":"case","label":"United States v. Vonn","cite":"535 U.S. 55","y":2002,"id":"2001/00-973","sc":1,"op":1,"sum":"The Court held 8-1 that silent defendant has the burden to satisfy the plain-error rule and unanimously that a reviewing court may consult the whole record when considering the effect of any error on substantial rights.","sumSrc":"Oyez","by":{"0":"10, 17, 18, 19","1":"8, 10, 15, 19, 20, 34","2":"5"}},{"t":"case","label":"United States v. Young","cite":"470 U.S. 1","y":1985,"id":"1984/83-469","sc":1,"sum":"The prosecutor's remarks during the rebuttal argument, although error, did not constitute \"plain error\" that a reviewing court could properly act on under Federal Rule of Criminal Procedure 52(b), absent a timely objection by defense counsel; on the record, the challenged argument did not undermine the fairness of the trial.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17, 24","1":"8, 15, 17, 18, 24, 31"}},{"t":"case","label":"Washington v. Texas","cite":"388 U.S. 14","y":1967,"id":"1966/649","sc":1,"sum":"The Supreme Court held that the Sixth Amendment right to compulsory process is so fundamental that it is incorporated in the due process clause of the Fourteenth Amendment. Washington was denied that right in this case. Justice John M. Harlan concurred in the result, writing that Washington’s right to due process was violated, but the compulsory process clause played no role in his decision.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Wiborg v. United States","cite":"163 U.S. 632","y":1896,"id":"scdb/1895-269","sc":1,"ar":2,"sum":"The several acts described iu and made punishable by Rev. Stat. § 5286, are stated therein separately and disjunctively, connected by the conjunction “or.” The indictment in this case, charging that the defendants committed some of those acts, connects them by the conjunction “ and.” No question of duplicity was raised by the defendants’ counsel. The trial judge instructed the jury that the evidence would not …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"11, 12","1":"29","2":"2, 4"}},{"t":"case","label":"Williamson v. United States","cite":"512 U.S. 594","y":1994,"id":"1993/93-5256","sc":1,"sum":"The judgment is vacated, and the case is remanded. 981 F. 2d 1262, vacated and remanded. JUSTICE O'CONNOR delivered the opinion of the Court with respect to Parts I, II-A, and II-B, concluding:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"11"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(g)","(g)(1)"],"stext":{"head":"§922. Unlawful acts","paras":[[0,"(a) It shall be unlawful—"],[1,"(1) for any person—"],[2,"(A) except a licensed importer, licensed manufacturer, or licensed dealer, to engage in the business of importing, manufacturing, or dealing in firearms, or in the course of such business to ship, transport, or receive any firearm in interstate or foreign commerce; or"],[2,"(B) except a licensed importer or licensed manufacturer, to engage in the business of importing or manufacturing ammunition, or in the course of such business, to ship, transport, or receive any ammunition in interstate or foreign commerce;"],[1,"(2) for any importer, manufacturer, dealer, or collector licensed under the provisions of this chapter to ship or transport in interstate or foreign commerce any firearm to any person other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, except that—"],[2,"(A) this paragraph and subsection (b)(3) shall not be held to preclude a licensed importer, licensed manufacturer, licensed dealer, or licensed collector from returning a firearm or replacement firearm of the same kind and type to a person from whom it was received; and this paragraph shall not be held to preclude an individual from mailing a firearm owned in compliance with Federal, State, and local law to a licensed importer, licensed manufacturer, licensed dealer, or licensed collector;"],[2,"(B) this paragraph shall not be held to preclude a licensed importer, licensed manufacturer, or licensed dealer from depositing a firearm for conveyance in the mails to any officer, employee, agent, or watchman who, pursuant to the provisions of section 1715 of this title, is eligible to receive through the mails pistols, revolvers, and other firearms capable of being concealed on the person, for use in connection with his official duty; and"],[2,"(C) nothing in this paragraph shall be construed as applying in any manner in the District of Columbia, the Commonwealth of Puerto Rico, or any possession of the United States differently than it would apply if the District of Columbia, the Commonwealth of Puerto Rico, or the possession were in fact a State of the United States;"],[1,"(3) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector to transport into or receive in the State where he resides (or if the person is a corporation or other business entity, the State where it maintains a place of business) any firearm purchased or otherwise obtained by such person outside that State, except that this paragraph (A) shall not preclude any person who lawfully acquires a firearm by bequest or intestate succession in a State other than his State of residence from transporting the firearm into or receiving it in that State, if it is lawful for such person to purchase or possess such firearm in that State, (B) shall not apply to the transportation or receipt of a firearm obtained in conformity with subsection (b)(3) of this section, and (C) shall not apply to the transportation of any firearm acquired in any State prior to the effective date of this chapter;"],[1,"(4) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, to transport in interstate or foreign commerce any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity;"],[1,"(5) for any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) to transfer, sell, trade, give, transport, or deliver any firearm to any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) who the transferor knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the transferor resides; except that this paragraph shall not apply to (A) the transfer, transportation, or delivery of a firearm made to carry out a bequest of a firearm to, or an acquisition by intestate succession of a firearm by, a person who is permitted to acquire or possess a firearm under the laws of the State of his residence, and (B) the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(6) for any person in connection with the acquisition or attempted acquisition of any firearm or ammunition from a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, knowingly to make any false or fictitious oral or written statement or to furnish or exhibit any false, fictitious, or misrepresented identification, intended or likely to deceive such importer, manufacturer, dealer, or collector with respect to any fact material to the lawfulness of the sale or other disposition of such firearm or ammunition under the provisions of this chapter;"],[1,"(7) for any person to manufacture or import armor piercing ammunition, unless—"],[2,"(A) the manufacture of such ammunition is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) the manufacture of such ammunition is for the purpose of exportation; or"],[2,"(C) the manufacture or importation of such ammunition is for the purpose of testing or experimentation and has been authorized by the Attorney General;"],[1,"(8) for any manufacturer or importer to sell or deliver armor piercing ammunition, unless such sale or delivery—"],[2,"(A) is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) is for the purpose of exportation; or"],[2,"(C) is for the purpose of testing or experimentation and has been authorized by the Attorney General; 1"],[1,"(9) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, who does not reside in any State to receive any firearms unless such receipt is for lawful sporting purposes."],[0,"(b) It shall be unlawful for any licensed importer, licensed manufacturer, licensed dealer, or licensed collector to sell or deliver—"],[1,"(1) any firearm or ammunition to any individual who the licensee knows or has reasonable cause to believe is less than eighteen years of age, and, if the firearm, or ammunition is other than a shotgun or rifle, or ammunition for a shotgun or rifle, to any individual who the licensee knows or has reasonable cause to believe is less than twenty-one years of age;"],[1,"(2) any firearm to any person in any State where the purchase or possession by such person of such firearm would be in violation of any State law or any published ordinance applicable at the place of sale, delivery or other disposition, unless the licensee knows or has reasonable cause to believe that the purchase or possession would not be in violation of such State law or such published ordinance;"],[1,"(3) any firearm to any person who the licensee knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the licensee's place of business is located, except that this paragraph (A) shall not apply to the sale or delivery of any rifle or shotgun to a resident of a State other than a State in which the licensee's place of business is located if the transferee meets in person with the transferor to accomplish the transfer, and the sale, delivery, and receipt fully comply with the legal conditions of sale in both such States (and any licensed manufacturer, importer or dealer shall be presumed, for purposes of this subparagraph, in the absence of evidence to the contrary, to have had actual knowledge of the State laws and published ordinances of both States), and (B) shall not apply to the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(4) to any person any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity; and"],[1,"(5) any firearm or armor-piercing ammunition to any person unless the licensee notes in his records, required to be kept pursuant to section 923 of this chapter, the name, age, and place of residence of such person if the person is an individual, or the identity and principal and local places of business of such person if the person is a corporation or other business entity."],[0,"Paragraphs (1), (2), (3), and (4) of this subsection shall not apply to transactions between licensed importers, licensed manufacturers, licensed dealers, and licensed collectors. Paragraph (4) of this subsection shall not apply to a sale or delivery to any research organization designated by the Attorney General."],[0,"(c) In any case not otherwise prohibited by this chapter, a licensed importer, licensed manufacturer, or licensed dealer may sell a firearm to a person who does not appear in person at the licensee's business premises (other than another licensed importer, manufacturer, or dealer) only if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/922?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§922. Unlawful acts","tname":"Crimes and Criminal Procedure","by":{"0":"36","1":"37, 41, 37, 41"}},{"t":"usc","label":"18 U.S.C. § 3661","url":"https://www.law.cornell.edu/uscode/text/18/3661","by":{"0":"37"}},{"t":"rule","label":"Fed. R. Crim. P. 32","url":"https://www.law.cornell.edu/rules/frcrmp/rule_32","by":{"0":"35, 36, 37"}},{"t":"rule","label":"Fed. R. Crim. P. 52","url":"https://www.law.cornell.edu/rules/frcrmp/rule_52","subs":["(b)"],"by":{"0":"6, 9, 11","2":"1, 5, 5"}},{"t":"rule","label":"Fed. R. Evid. 401","url":"https://www.law.cornell.edu/rules/fre/rule_401","by":{"0":"24"}},{"t":"rule","label":"Fed. R. Evid. 403","url":"https://www.law.cornell.edu/rules/fre/rule_403","by":{"0":"24"}},{"t":"rule","label":"Fed. R. Evid. 704","url":"https://www.law.cornell.edu/rules/fre/rule_704","subs":["(b)"],"by":{"0":"24"}},{"t":"rule","label":"Fed. R. Crim. P. 11","url":"https://www.law.cornell.edu/rules/frcrmp/rule_11","subs":["(h)"],"by":{"0":"19"}},{"t":"case","label":"Brady v. Maryland","cite":"373 U.S. 83","y":1963,"id":"1962/490","sc":1,"sum":"The Supreme Court held that the prosecution's suppression of evidence violated the Due Process Clause of the Fourteenth Amendment. The Court also held that according the Maryland state law, the confession would not exonerate Brady, so a remand only for reconsidering his punishment was proper.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Chapman v. California","cite":"386 U.S. 18","y":1967,"id":"1966/95","sc":1,"sum":"Justice Black determined that federal law must govern the application of a state harmless error rule; the Court cannot leave the formulation of rules protecting individuals from invasion by the states to those very same states.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Delaware v. Van Arsdall","cite":"475 U.S. 673","y":1986,"id":"1985/84-1279","sc":1,"sum":"While the trial court's denial of respondent's opportunity to impeach the prosecution witness for bias violated respondent's rights under the Confrontation Clause, such ruling is subject to harmless-error analysis under Chapman v. California, 386 U. S.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18, 28","2":"6"}},{"t":"case","label":"Gardner v. Florida","cite":"430 U.S. 349","y":1977,"id":"1976/74-6593","sc":1,"sum":"The judgment is vacated and the case is remanded. Pp. 355-364. 313 So. 2d 675, vacated and remanded. MR. JUSTICE STEVENS, joined by MR. JUsTIcE STEWART and MR. JUSTICE POWELL, concluded that:","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"35, 36"}},{"t":"case","label":"Head v. Hargrave","cite":"105 U.S. 45","y":1882,"id":"scdb/1881-157","sc":1,"sum":"This was an action brought iñ a district court of.Arizona to recover the sum of -$2,0Q0 alleged to be owing by the defendants-to the plaintiffs for professional services as attorneys and counsellors-at-law in that Territory in 1877. and 1878. The complaint alleges that the services wére performed,in several-suits and proceedings, upon a retainer by the^ defendants; and that they were reasonably worth that sum. The …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"39"}},{"t":"case","label":"Henderson v. Kibbe","cite":"431 U.S. 145","y":1977,"id":"1976/75-1906","sc":1,"sum":"The trial judge's failure to instruct the jury on 'he issue of causation was not constitutional error requiring the District Court to grant habeas corpus relief. Pp. 153-157 (a) The onussion of the causation instruction did not create a danger that the jury failed to make an essential factual determination as required by Winship, supra, where there can be no question from the record that the jurors were informed …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Henderson v. United States","cite":"568 U.S. 266","y":2013,"id":"2012/11-9307","sc":1,"sum":"The Court held that the determination of “plain error” is made during the appellate review, not during the trial.","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"Johnson v. United States","cite":"318 U.S. 189","y":1943,"id":"scdb/1942-124","sc":1,"by":{"1":"17"}},{"t":"case","label":"Jones v. United States","cite":"527 U.S. 373","y":1999,"id":"1998/97-9361","sc":1,"op":3,"sum":"The Court held that Jones was not entitled to an instruction as to the effect of jury deadlock. The Court held that the Eighth Amendment does not require such an instruction and the Court declined to exercise its supervisory powers to require such an instruction in every capital case.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"Luce v. United States","cite":"469 U.S. 38","y":1984,"id":"1984/83-912","sc":1,"sum":"To raise and preserve for review the claim of improper impeachment with a prior conviction, a defendant must testify. To perform the weighing of the prior conviction's probative value against its prejudicial effect, as required by Rule 609(a)(1), the reviewing court must know the precise nature of the defendant's testimony, which is unknowable when, as here, the defendant does not testify. Any possible harm flowing …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15"}},{"t":"case","label":"Old Chief v. United States","cite":"519 U.S. 172","y":1997,"id":"1996/95-6556","sc":1,"op":1,"ar":16,"sum":"The Court ruled that a district court abuses its discretion under the Federal Rules of Evidence if it spurns a defendant's offer to concede a prior judgment and admits the full judgment record over the defendant's objection, when the name or nature of the prior offense raises the risk of a verdict tainted by improper considerations, and when the purpose of the evidence is solely to prove the element of prior conviction.","sumSrc":"Oyez","by":{"1":"25, 35","2":"14"}},{"t":"case","label":"Parker v. Matthews","cite":"567 U.S. 37","y":2012,"id":"2011/11-845","sc":1,"sum":"The Court found that the Sixth Circuit improperly used its own precedent in deciding an appeal from a murder conviction, and that circuit precedent does not constitute clearly established federal law, so it cannot form the basis for habeas relief.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Puckett v. United States","cite":"556 U.S. 129","y":2009,"id":"2008/07-9712","sc":1,"op":3,"sum":"The Court found that the \"plain error standard\" of Rule 52(b) of the Federal Rules of Criminal Procedure governs if claims forfeited at trial may be raised at the appellate level.","sumSrc":"Oyez","by":{"1":"13, 14, 15, 22, 24","2":"12, 14"}},{"t":"case","label":"Rose v. Clark","cite":"478 U.S. 570","y":1986,"id":"1985/84-1974","sc":1,"sum":"Respondent was charged with the murder of two persons arising from the same incident. At his trial in a Tennessee state court he defended on the ground, inter alia, that he was either insane or incapable of forming the requisite intent to kill the victims. The court instructed the jury on both first-degree murder, which requires proof of premeditation and deliberation under Tennessee law, and second-degree murder, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"Strickland v. Washington","cite":"466 U.S. 668","y":1984,"id":"1983/82-1554","sc":1,"sum":"The Supreme Court held that: (1) counsel's performance must be deficient; and (2) the deficient performance must have prejudiced the defense so as to deprive the defendant of a fair trial.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"United States v. Atkinson","cite":"297 U.S. 157","y":1936,"id":"scdb/1935-082","sc":1,"sum":"In the absence of exceptional circumstances, error in a jury trial, which was not brought to the attention of the court by proper exception or request to charge, will not be considered on appeal. P. 159. 76 F. (2d) 564, affirmed. CERTIORARI, 296 U. S. 559, to review a judgment affirming a judgment against the United States in an action on a policy of converted war risk insurance. Mr. Will G. Beardslee, with whom …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"42"}},{"t":"case","label":"United States v. Caudle","cite":"968 F.3d 916","y":2020,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/968/916/","by":{"1":"27"}},{"t":"case","label":"United States v. Davila","cite":"569 U.S. 597","y":2013,"id":"2012/12-167","sc":1,"op":1,"sum":"The Court held that a magistrate judge's improper participation in plea discussions does not warrant vacating a guilty plea.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"United States v. Frady","cite":"456 U.S. 152","y":1982,"id":"1981/80-1595","sc":1,"sum":"In 1963, respondent was convicted of first-degree murder and sentenced to death by a jury in the Federal District Court for the District of Columbia, which at that time had exclusive jurisdiction over local felonies committed in the District. The Court of Appeals for the District of Columbia Circuit, which then acted as the local appellate court, upheld the conviction but set aside the death sentence, and respondent …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15, 19"}},{"t":"case","label":"United States v. Games-Perez","cite":"695 F.3d 1104","y":2012,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/695/1104/","by":{"1":"28"}},{"t":"case","label":"United States v. Gary","cite":"963 F.3d 420","y":2020,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/963/420/","op":41,"by":{"1":"39"}},{"t":"case","label":"United States v. Gomez","cite":"705 F.3d 68","y":2013,"url":"https://www.courtlistener.com/c/F.3d/705/68/","by":{"1":"27"}},{"t":"case","label":"United States v. Lavalais","cite":"960 F.3d 180","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/960/180/","op":1,"by":{"1":"39"}},{"t":"case","label":"United States v. Lespier","cite":"725 F.3d 437","y":2013,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/725/437/","by":{"1":"27"}},{"t":"case","label":"United States v. Mancillas","cite":"789 Fed. Appx. 549","y":2020,"court":"7th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./789/549/","by":{"1":"26"}},{"t":"case","label":"United States v. McGhee","cite":"651 F.3d 153","y":2011,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/651/153/","by":{"1":"37"}},{"t":"case","label":"United States v. Medley","cite":"972 F.3d 399","y":2020,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/972/399/","by":{"1":"32"}},{"t":"case","label":"United States v. Miller","cite":"954 F.3d 551","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/954/551/","by":{"1":"25"}},{"t":"case","label":"United States v. Moore","cite":"954 F.3d 1322","y":2020,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/954/1322/","by":{"1":"27"}},{"t":"case","label":"United States v. Owens","cite":"966 F.3d 700","y":2020,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/966/700/","by":{"1":"26"}},{"t":"case","label":"United States v. Rosales-Bruno","cite":"789 F.3d 1249","y":2015,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/789/1249/","by":{"1":"37"}},{"t":"case","label":"United States v. Sandford","cite":"814 Fed. Appx. 649","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./814/649/","by":{"1":"26"}},{"t":"case","label":"United States v. Spencer","cite":"813 Fed. Appx. 385","y":2020,"court":"11th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./813/385/","by":{"1":"26"}},{"t":"case","label":"United States Department of Justice v. Julian","cite":"486 U.S. 1","y":1988,"id":"1987/86-1357","sc":1,"op":2,"ar":35,"sum":"The FOIA requires that the presentence reports be disclosed by petitioners, except as to matters relating to confidential sources, diagnostic opinions, and possibly harmful information.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"36"}},{"t":"case","label":"Wainwright v. Sykes","cite":"433 U.S. 72","y":1977,"id":"1976/75-1578","sc":1,"sum":"Respondent's failure to make timely objection under the Florida contemporaneous-objection rule to the admission of his inculpatory statements, absent a showing of cause for the noncompliance and some showing of actual prejudice, bars federal habeas corpus review of his Miranda claim. Davis v. United States, 411 U. S. 233; Francis v. Henderson,425 U. S. 536.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15"}},{"t":"case","label":"Washington v. Recuenco","cite":"548 U.S. 212","y":2006,"id":"2005/05-83","sc":1,"sum":"In a 7-to-2 decision authored by Justice Clarence Thomas, the Supreme Court held that Blakely violations do not \"necessarily render[] a criminal trial unfair or an unreliable vehicle for determining guilt or innocence.\" (quoting Neder v. United States , 527 U.S. 1) As such, the defendant is not entitled to an automatic reversal and the prosecution may attempt to argue that the jury would have returned the same result if the error had not occurred.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Wong v. Belmontes","cite":"558 U.S. 15","y":2009,"id":"2009/08-1263","sc":1,"sum":"The Court held that a death row inmate's attorney did not undermine his conviction.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Yakus v. United States","cite":"321 U.S. 414","y":1944,"id":"1940-1955/321us414","sc":1,"sum":"The Supreme Court held that Congress sufficiently regulated the powers of the Administrator of the Act in such a way as to be a constitutional delegation of legislative power to obtain a particular objective. The Constitution grants Congress the necessary flexibility to perform its legislative function in a variety of ways.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(a)(2)"],"by":{"1":"37, 41"}},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","subs":["(a)","(a)(1)"],"by":{"1":"37, 41, 37"}},{"t":"case","label":"Cole v. Arkansas","cite":"333 U.S. 196","y":1948,"id":"scdb/1947-046","sc":1,"sum":"Petitioners were tried in a state court under an information charging them only with a violation of § 2 of a state statute, making it an offense to promote an unlawful assemblage. The trial court instructed the jury that they were charged with an offense under § 2; and they were convicted. They appealed to the State Supreme Court, contending, inter alia, that § 2 was contrary to the Federal …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"8"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"Douglas v. California","cite":"372 U.S. 353","y":1963,"id":"1961/34","sc":1,"sum":"The Court held that California’s treatment of defendants changed depending on whether the defendant could afford counsel. Indigent defendants, potentially with “hidden merit” in their appeals, could not meaningfully appeal convictions when courts conducted reviews without input from the defendant’s attorney.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Evitts v. Lucey","cite":"469 U.S. 387","y":1985,"id":"1984/83-1378","sc":1,"sum":"The Due Process Clause of the Fourteenth Amendment guarantees a criminal defendant the effective assistance of counsel on his first appeal as of right.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"17"}},{"t":"case","label":"Galloway v. United States","cite":"319 U.S. 372","y":1943,"id":"scdb/1942-050","sc":1,"sum":"1. In this suit against the United States to recover benefits under a contract of war risk insurance, on account of alleged total and permanent disability resulting from insanity of the insured while the policy was in force, held that the evidence was insufficient to support a judgment for the plaintiff and the trial court properly granted the Government's motion for a directed verdict.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"Griffin v. Illinois","cite":"351 U.S. 12","y":1956,"id":"1955/95","sc":1,"sum":"In a 5–4 decision authored by Justice Hugo L. Black, the Court reasoned that there is \"no meaningful distinction\" between denying indigent defendants the right to appeal and denying them a trial. Because Illinois conceded that Griffin and Crenshaw could not file for appeal without a transcript, the Court found that their rights to due process and equal protection had been denied.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Jones v. Barnes","cite":"463 U.S. 745","y":1983,"id":"1982/81-1794","sc":1,"sum":"Defense counsel assigned to prosecute an appeal from a criminal conviction does not have a constitutional duty to raise every nonfrivolous issue requested by the defendant. The accused has the ultimate authority to make certain fundamental decisions regarding his case, including the decision whether to take an appeal; and, with some limitations, he may elect to act as his own advocate. However, an indigent defendant …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"17"}},{"t":"case","label":"United States v. Cotton","cite":"35 U.S. 625","y":2002,"id":"scdb/1836-051","sc":1,"op":1,"sum":"Archibald M’Learn, a native of Scotland, and afterwards a citizen of the United States, purchased a tract of land called Gowrie, and a small island, in Chatham county, in the state of Georgia, on which he established a rice plantation; and having paid part, of the purchase money, a judgment was obtained against him for the balance. He died, having devised' the whole of his estate, real and personal, to his son, …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"8, 12, 13, 14"}},{"t":"case","label":"United States v. Games-Perez","cite":"667 F.3d 1136","y":2012,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/667/1136/","by":{"2":"9"}},{"t":"case","label":"United States v. Titties","cite":"852 F.3d 1257","y":2017,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/852/1257/","by":{"2":"15"}},{"t":"case","label":"United States v. Wiltberger","cite":"18 U.S. 76","y":1820,"id":"scdb/1820-003","sc":1,"sum":"The United States v. Wiltberger.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"10"}},{"t":"case","label":"Wall v. Kholi","cite":"562 U.S. 545","y":2011,"id":"2010/09-868","sc":1,"sum":"The Court held that the one-year window of time in which an inmate may file a habeas challenge to their sentence in federal court after conviction is delayed while a state court considers an inmate's request for a sentence reduction.","sumSrc":"Oyez","by":{"2":"16"}},{"t":"rule","label":"Fed. R. Crim. P. 6","url":"https://www.law.cornell.edu/rules/frcrmp/rule_6","by":{"2":"6"}}]};